function buildTrendLineOptions(labels, planSeries, receiptSeries, remainSeries, chartHeight, isFullscreen) {
    return {
        series: [
            { name: "Phải thu", data: planSeries },
            { name: "Đã thu", data: receiptSeries },
            { name: "Còn nợ", data: remainSeries }
        ],
        chart: Object.assign({}, baseChartOpts, {
            type: "line",
            height: chartHeight,
            zoom: { enabled: isFullscreen === true, type: "x", autoScaleYaxis: true }
        }),
        colors: [INFO, SUCCESS, DANGER],
        stroke: {
            curve: "smooth",
            width: isFullscreen ? 3 : 2.5
        },
        fill: {
            type: "gradient",
            gradient: {
                shade: "light",
                type: "vertical",
                shadeIntensity: 0.35,
                gradientToColors: ["#93c5fd", "#86efac", "#fca5a5"],
                opacityFrom: isFullscreen ? 0.45 : 0.35,
                opacityTo: 0.05,
                stops: [0, 85, 100]
            }
        },
        markers: {
            size: isFullscreen ? 5 : 4,
            strokeWidth: 2,
            strokeColors: "#fff",
            hover: { size: 7 }
        },
        dataLabels: { enabled: false },
        xaxis: {
            categories: labels,
            labels: {
                rotate: labels.length > 8 ? -35 : -20,
                trim: true,
                maxHeight: isFullscreen ? 120 : 72,
                style: { fontSize: isFullscreen ? "11px" : "10px" }
            },
            axisBorder: { show: false },
            axisTicks: { show: false }
        },
        yaxis: {
            labels: {
                formatter: function (val) {
                    return formatMoney(val);
                }
            }
        },
        legend: {
            position: "top",
            horizontalAlign: "right",
            fontWeight: 600
        },
        grid: {
            borderColor: "#e2e8f0",
            strokeDashArray: 4
        },
        tooltip: {
            shared: true,
            intersect: false,
            y: {
                formatter: function (val) {
                    return formatMoney(val);
                }
            }
        }
    };
}

function renderTrendChart(rows) {
    var labels = [];
    var planSeries = [];
    var receiptSeries = [];
    var remainSeries = [];
    var i;

    rows = rows || [];
    for (i = 0; i < rows.length; i++) {
        labels.push(rows[i].SegmentLabel || ("Đợt " + (i + 1)));
        planSeries.push(rows[i].PlanMoney || 0);
        receiptSeries.push(rows[i].ReceiptMoney || 0);
        remainSeries.push(rows[i].RemainMoney || 0);
    }

    if (labels.length === 0) {
        destroyChart("#stdDashChartTrend");
        toggleChartEmpty("#stdDashChartTrend", "stdDashChartTrendEmpty", true);
        delete fullscreenStates.trend;
        return;
    }

    toggleChartEmpty("#stdDashChartTrend", "stdDashChartTrendEmpty", false);
    renderChart("#stdDashChartTrend", buildTrendLineOptions(
        labels,
        planSeries,
        receiptSeries,
        remainSeries,
        320,
        false
    ), "stdDashChartTrendEmpty");

    registerFullscreen("trend", "Diễn biến thu nợ theo đợt thu", function () {
        var fsHeight = Math.max(window.innerHeight - 140, 420);
        return buildTrendLineOptions(
            labels,
            planSeries,
            receiptSeries,
            remainSeries,
            fsHeight,
            true
        );
    }, "line");
}

